import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*')):
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith(('!Sample_title','!Sample_characteristics','!Sample_source','!Series_title','!Series_summary','!Series_overall','!Sample_description')):
