import gzip,glob
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    print('=====',f)
    for l in gzip.open(f,'rt',errors='ignore'):
        if l.startswith('!series_matrix_table_begin'): break
        p=l.rstrip('\n').split('\t')
        if p[0].startswith(('!Sample_title','!Sample_characteristics','!Sample_source','!Sample_description','!Series_title','!Series_overall','!Sample_growth','!Sample_treatment','!Series_contrib','!Sample_contact_inst','!Sample_contact_name')):
            u=list(dict.fromkeys(p[1:]))
            print(p[0], len(u), u[:80] if p[0]!='!Sample_title' else p[1:])

